import{VicePresidentCard}from"./VicePresidentCard.js";export function TimelineItem(e,i){return`\n        <div class="timeline-item" data-target="vp-${i}">\n            <div class="timeline-dot"></div>\n            <div class="timeline-year-label">${e.electionYear.substring(0,4)}</div>\n            <div class="timeline-content">\n                ${VicePresidentCard(e,i)}\n            </div>\n        </div>\n    `}